const source = [
  $json.textPlain,
  $json.textHtml,
  $json.html,
  $json.text,
  $json.body,
  $json.snippet,
]
  .map(value => String(value ?? ''))
  .find(value => value.trim()) ?? '';
if (!source.trim()) {
  throw new Error('El correo no contiene un cuerpo que se pueda analizar.');
}

const decodeEntities = (value) => value
  .replace(/&nbsp;|&#160;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&euro;|&#x20ac;|&#8364;/gi, '€')
  .replace(/&quot;/gi, '"')
  .replace(/&#39;|&apos;/gi, "'")
  .replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>')
  .replace(/&#(\d+);/g, (_, code) => String.fromCharCode(Number(code)))
  .replace(/&#x([0-9a-f]+);/gi, (_, code) => String.fromCharCode(parseInt(code, 16)));

const raw = decodeEntities(
  source
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|li|tr|td|th|h[1-6]|section|article|table)>/gi, '\n')
    .replace(/<[^>]+>/g, ' '),
);
const lines = raw
  .split(/\r?\n/)
  .map(line => line.replace(/\s+/g, ' ').trim())
  .filter(Boolean);

const metadata = [
  $json.subject,
  $json.from,
  $json.sender,
  $json.headers?.subject,
  $json.headers?.Subject,
  $json.headers?.from,
  $json.headers?.From,
]
  .map(value => String(value ?? ''))
  .join(' ');
const isVinted = /vinted/i.test(metadata)
  || lines.some(line => /has vendido un art[ií]culo en vinted/i.test(line));
const canal = isVinted ? 'Vinted' : 'Wallapop';

const parsePrice = (line) => {
  const match = line.match(/((?:\d{1,3}(?:[.\s]\d{3})*|\d+)(?:[.,]\d{1,2})?)\s*€\s*$/);
  if (!match) return null;

  const rawPrice = match[1].replace(/\s/g, '');
  let importe;
  if (rawPrice.includes(',')) {
    importe = Number(rawPrice.replace(/\./g, '').replace(',', '.'));
  } else if (rawPrice.includes('.')) {
    const parts = rawPrice.split('.');
    importe = parts.length > 1 && parts[parts.length - 1].length === 3
      ? Number(parts.join(''))
      : Number(rawPrice);
  } else {
    importe = Number(rawPrice);
  }

  return Number.isFinite(importe) ? { match, value: importe } : null;
};

const dateFromValue = (value) => {
  const text = String(value ?? '').trim();
  if (!text) return null;

  const isoMatch = text.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (isoMatch) return isoMatch[0];

  const spanishMatch = text.match(/\b(\d{1,2})[./-](\d{1,2})[./-](\d{2,4})\b/);
  if (spanishMatch) {
    const year = spanishMatch[3].length === 2 ? '20' + spanishMatch[3] : spanishMatch[3];
    return year + '-' + spanishMatch[2].padStart(2, '0') + '-' + spanishMatch[1].padStart(2, '0');
  }

  const timestamp = /^\d{10,}$/.test(text) ? Number(text) : text;
  const parsed = new Date(timestamp);
  if (Number.isNaN(parsed.getTime())) return null;
  return parsed.getFullYear() + '-'
    + String(parsed.getMonth() + 1).padStart(2, '0') + '-'
    + String(parsed.getDate()).padStart(2, '0');
};

const firstPriceAt = (start) => lines.findIndex((line, index) => index >= start && parsePrice(line));

let fecha;
let comprador_nombre;
let titulo_producto;
let importe_total;

if (canal === 'Vinted') {
  const boughtAt = lines.findIndex(line => /\bha comprado\b/i.test(line));
  const buyerMatch = boughtAt >= 0
    ? lines[boughtAt].match(/^(.+?)\s+ha comprado\b/i)
    : null;
  if (!buyerMatch) {
    throw new Error('No se encontro el bloque de comprador de Vinted.');
  }
  comprador_nombre = buyerMatch[1].trim();

  const priceAt = firstPriceAt(boughtAt + 1);
  if (priceAt < 0) {
    throw new Error('No se encontro el importe en el correo de Vinted.');
  }
  const parsedPrice = parsePrice(lines[priceAt]);
  const titleOnPriceLine = parsedPrice
    ? lines[priceAt].slice(0, parsedPrice.match.index).trim()
    : '';
  titulo_producto = titleOnPriceLine || lines[priceAt - 1] || '';
  if (!titulo_producto || priceAt <= boughtAt) {
    throw new Error('No se encontro el titulo del producto de Vinted.');
  }
  importe_total = parsedPrice?.value;
  if (!Number.isFinite(importe_total)) {
    throw new Error('No se encontro el importe en el correo de Vinted.');
  }

  fecha = [
    $json.date,
    $json.internalDate,
    $json.internal_date,
    $json.receivedAt,
    $json.timestamp,
    $json.headers?.date,
    $json.headers?.Date,
  ].map(dateFromValue).find(Boolean);
  if (!fecha) {
    throw new Error('No se encontro la fecha del mensaje de Vinted.');
  }
} else {
  const boughtAt = lines.findIndex(line => /^Comprado por:?$/i.test(line));
  if (boughtAt < 0 || !lines[boughtAt + 1]) {
    throw new Error('No se encontro el bloque Comprado por en el correo de Wallapop.');
  }
  comprador_nombre = lines[boughtAt + 1];

  const productStart = boughtAt + 2;
  const inlinePrice = parsePrice(lines[productStart]);
  if (inlinePrice) {
    titulo_producto = lines[productStart].slice(0, inlinePrice.match.index).trim();
    importe_total = inlinePrice.value;
  } else {
    const priceAt = firstPriceAt(productStart);
    const parsedPrice = priceAt >= 0 ? parsePrice(lines[priceAt]) : null;
    const titleLine = priceAt > productStart ? lines[priceAt - 1] : '';
    if (!parsedPrice || !titleLine || parsePrice(titleLine)) {
      throw new Error('No se encontro el producto y su importe en el correo de Wallapop.');
    }
    titulo_producto = titleLine;
    importe_total = parsedPrice.value;
  }

  if (!titulo_producto || !Number.isFinite(importe_total)) {
    throw new Error('No se encontro el producto y su importe en el correo de Wallapop.');
  }

  const dateAt = lines.findIndex(line => /^Fecha de compra:/i.test(line));
  const dateCandidates = dateAt >= 0
    ? [
        lines[dateAt].replace(/^Fecha de compra:\s*/i, ''),
        lines[dateAt + 1],
      ]
    : [];
  fecha = dateCandidates.map(dateFromValue).find(Boolean);
  if (!fecha) {
    throw new Error('No se encontro la fecha de compra en el correo de Wallapop.');
  }
}

const origen_id = String(
  $json.id
    ?? $json.messageId
    ?? $json.message_id
    ?? $json.threadId
    ?? '',
).trim();
if (!origen_id) {
  throw new Error('El disparador de Gmail no devolvio un id estable del mensaje.');
}

return [{
  json: {
    proyecto_id: Number($env.ERP_PROJECT_ID || 1),
    origen_id,
    canal,
    fecha,
    comprador_nombre,
    titulo_producto,
    importe_total,
    unidades: 1,
  },
}];
